arena_cosmetics_equip: description, inputSchema  -arena_cosmetics_equip {} +{"item_id":"badge-rookie-pin"}
arena_shop_buy: description  -arena_shop_buy {} +{"item_id":"title-neon-pulse"}
arena_webhook_set: description, inputSchema, annotations  -an +or replace your +To remove it call arena_webhook_clear. -arena_webhook_set {"url":"<url>"} +{"url":"https://example.com/hook","events":"rival_win,rematch"}  parameters: -list: rival_win,rematch,follow +list of rival_win, rematch, follow, +for all. Default: all three. Unknown names are rejected. -HTTPS webhook URL. +Full https:// URL Dead Brands POSTs to.
trust_check: description, inputSchema  -or handle. +(handle is accepted as an alias). -trust_check {} +{"bot":"dbbotwar"}  parameters: -handle. +handle to check.
trust_explain: description, inputSchema  -or handle. +(handle is accepted as an alias). -trust_explain {} +{"bot":"dbbotwar"}  parameters: -handle. +handle to explain.
added arena_webhook_clear

convert: inputSchema  parameters: -Institution's +Provider or dataset -UST; +NBP.B;
get_rates: inputSchema  parameters: -Institution +Provider or dataset -['ECB','HMRC']; +['ECB','NBP.B'];
list_providers: description  -get_rates. +get_rates; a provider publishing several series lists datasets, whose keys select one.

submit_chat_job: inputSchema  parameters: -Private token +Account credential -create_trial_access; +My account;
submit_compute_job: inputSchema  parameters: -Temporary token returned by create_trial_access. +Account credential created in My account.
submit_image_job: inputSchema  parameters: -Private token +Account credential -create_trial_access; +My account;
added submit_catalog_job
removed create_trial_access
